param([string]$Project='artifacts/runtime-ui-prefab-tests/UnitySource')
. (Join-Path $PSScriptRoot 'Assert-EngineExecutionAllowed.ps1')

$ErrorActionPreference='Stop';$Project=[IO.Path]::GetFullPath($Project);if(!$Project.StartsWith(([IO.Path]::GetFullPath('artifacts')+'\'),[StringComparison]::OrdinalIgnoreCase)){throw 'Private fixture only'}
& ($PSScriptRoot+'/sync-test-adapters.ps1') -Project $Project
$folder=$Project+'/Assets/RuntimeUIPrefab';New-Item $folder -ItemType Directory -Force|Out-Null
@'
using UnityEngine;
public class RuntimeUICounter:MonoBehaviour {public int Hits;public int Order;public int OffHits;public int Awakes;public int Enables;public int Starts;public int Disables;public GameObject Button;void Awake(){Awakes++;}void OnEnable(){Enables++;}void Start(){Starts++;}void OnDisable(){Disables++;}public void First(){Hits++;Order=1;}public void Second(){Order=Order*10+2;}public void Off(){OffHits++;}}
'@|Set-Content ($folder+'/RuntimeUICounter.cs')
@'
using UnityEngine;
public class RuntimeUIChild:MonoBehaviour {public int Hits;public void Hit(){Hits++;}}
'@|Set-Content ($folder+'/RuntimeUIChild.cs')
@'
using UnityEngine;using UnityEngine.SceneManagement;
public class RuntimeUIDriver:MonoBehaviour {
 public int Frame;public GameObject Source;public GameObject Dormant;public GameObject Disabled;public GameObject Quiet;public GameObject First;public GameObject Second;public GameObject Copy;public GameObject Sleeping;public GameObject Hidden;public GameObject Passive;public RuntimeUICounter A;public RuntimeUICounter B;public RuntimeUICounter C;public RuntimeUICounter D;public RuntimeUICounter E;public RuntimeUICounter F;
 void Update(){Frame++;if(Frame==2){First=Instantiate(Source);A=First.GetComponent<RuntimeUICounter>();}if(Frame==4){Second=Instantiate(Source);B=Second.GetComponent<RuntimeUICounter>();}if(Frame==6){Copy=Instantiate(First);C=Copy.GetComponent<RuntimeUICounter>();}if(Frame==8){Sleeping=Instantiate(Dormant);D=Sleeping.GetComponent<RuntimeUICounter>();}if(Frame==9){Sleeping.SetActive(true);}if(Frame==10){First.SetActive(false);}if(Frame==12){First.SetActive(true);}if(Frame==13){B.Button.SetActive(false);}if(Frame==14){B.Button.SetActive(true);}if(Frame==15){Hidden=Instantiate(Disabled);E=Hidden.GetComponent<RuntimeUICounter>();}if(Frame==16){Passive=Instantiate(Quiet);F=Passive.GetComponent<RuntimeUICounter>();}if(Frame==17){Destroy(First);}if(Frame==20){Destroy(Second);Destroy(Copy);Destroy(Passive);}if(Frame==22){SceneManager.LoadScene(1);}}
}
'@|Set-Content ($folder+'/RuntimeUIDriver.cs')
@'
using UnityEngine;using UnityEngine.UI;using UnityEngine.Events;using UnityEditor;using UnityEditor.Events;using UnityEditor.SceneManagement;
public static class EMPrepareUIPrefab {
 static GameObject Make(string name,bool active,bool enabled){var root=new GameObject(name,typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;root.GetComponent<Canvas>().enabled=enabled;var count=root.AddComponent<RuntimeUICounter>();var button=new GameObject("Action",typeof(RectTransform),typeof(Image),typeof(Button));button.transform.SetParent(root.transform,false);var rect=(RectTransform)button.transform;rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=new Vector2(40,-30);rect.sizeDelta=new Vector2(180,60);button.GetComponent<Image>().color=new Color(.8f,.3f,.15f,1);var child=button.AddComponent<RuntimeUIChild>();count.Button=button;button.GetComponent<Button>().transition=Selectable.Transition.None;var click=button.GetComponent<Button>().onClick;UnityEventTools.AddVoidPersistentListener(click,count.First);UnityEventTools.AddVoidPersistentListener(click,child.Hit);UnityEventTools.AddVoidPersistentListener(click,count.Second);UnityEventTools.AddVoidPersistentListener(click,count.Off);click.SetPersistentListenerState(3,UnityEventCallState.Off);if(name=="UIPassive")while(click.GetPersistentEventCount()>0)UnityEventTools.RemovePersistentListener(click,0);var label=new GameObject("Label",typeof(RectTransform),typeof(Text));label.transform.SetParent(button.transform,false);var text=label.GetComponent<Text>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.text="PORT";text.supportRichText=false;text.fontSize=20;text.alignment=TextAnchor.MiddleCenter;text.raycastTarget=false;root.SetActive(active);root.transform.localScale=Vector3.one;var asset=PrefabUtility.SaveAsPrefabAsset(root,"Assets/RuntimeUIPrefab/"+name+".prefab");Object.DestroyImmediate(root);return asset;}
 public static void Run(){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var driver=new GameObject("UI Prefab Driver").AddComponent<RuntimeUIDriver>();driver.Source=Make("UIActive",true,true);driver.Dormant=Make("UIDormant",false,true);driver.Disabled=Make("UIDisabled",true,false);driver.Quiet=Make("UIPassive",true,true);MonoImporter.SetExecutionOrder(MonoScript.FromMonoBehaviour(driver),-1000);EditorSceneManager.SaveScene(scene,"Assets/RuntimeUIPrefab/UIPrefab.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/RuntimeUIPrefab/UIPrefab.unity",true),new EditorBuildSettingsScene("Assets/RuntimeWorld/RuntimeMiddle.unity",true),new EditorBuildSettingsScene("Assets/RuntimeWorld/RuntimeFinal.unity",true)};AssetDatabase.SaveAssets();Debug.Log("RUNTIME_UI_PREFAB_FIXTURE_READY");}
}
'@|Set-Content ($Project+'/Assets/Editor/EMPrepareUIPrefab.cs')
$s=[Diagnostics.ProcessStartInfo]::new('C:/Program Files/Unity/Hub/Editor/6000.0.83f1/Editor/Unity.exe');$s.UseShellExecute=$false;$s.CreateNoWindow=$true;foreach($a in @('-batchmode','-nographics','-quit','-projectPath',$Project,'-executeMethod','EMPrepareUIPrefab.Run','-logFile',($Project+'/prepare-ui-prefab.log'))){$s.ArgumentList.Add($a)};$p=[Diagnostics.Process]::Start($s);$p.WaitForExit();if($p.ExitCode-ne 0){throw 'UI prefab fixture failed'};Write-Output 'RUNTIME_UI_PREFAB_FIXTURE_READY'
